# Adım 1: Makine bazında topla
production_by_machine = {}
for row in sql_data.get('Production', []):
    machine = row.get('machine')
    qty = row.get('qty', 0) or 0
    if machine:
        if machine not in production_by_machine:
            production_by_machine[machine] = 0
        production_by_machine[machine] += qty

scrap_by_machine = {}
for row in sql_data.get('Scrap', []):
    machine = row.get('machine')
    qty = row.get('qty', 0) or 0
    if machine:
        if machine not in scrap_by_machine:
            scrap_by_machine[machine] = 0
        scrap_by_machine[machine] += qty

# Adım 2: Sadece Production'da olan makineleri al ve net hesapla
net_production = []
for machine, prod_qty in production_by_machine.items():
    if not machine:
        continue
    scrap_qty = scrap_by_machine.get(machine, 0)
    net_qty = prod_qty - scrap_qty
    net_production.append({'machine': machine, 'net_qty': net_qty})

out('net_production').append(net_production)
